fault_script:
#!/bin/bash
set -euo pipefail
exec >>/home/phat/ml-experiments/8b8ec15ce381/fault.log 2>&1
echo FAULT_BEFORE $(date -u +%s)
systemctl stop zabbix-agent2
test "$(systemctl is-active zabbix-agent2)" = inactive
echo FAULT_VERIFIED $(date -u +%s)

rollback_script:
